package factorycraft.gametest;

import factorycraft.FactoryCraft;
import factorycraft.blockentity.*;
import factorycraft.blocks.*;
import factorycraft.multiblock.*;
import factorycraft.research.*;
import factorycraft.registry.Content;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.item.*;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.neoforged.neoforge.gametest.*;
import java.util.*;

@GameTestHolder(FactoryCraft.ID)
@PrefixGameTestTemplate(false)
public final class ResearchGameTests {
    private static ResourceLocation id(String path){return ResourceLocation.fromNamespaceAndPath(FactoryCraft.ID,path);}
    private static LabBlockEntity lab(GameTestHelper h,int x,String scope){var pos=h.absolutePos(new BlockPos(x,2,4));StructurePlacement.place(h.getLevel(),pos,Content.FACTORY.get(FactoryKind.LAB).get().defaultBlockState());var lab=(LabBlockEntity)h.getLevel().getBlockEntity(pos);lab.bind(scope);return lab;}
    private static String personal(GameTestHelper h,String name){var uuid=UUID.nameUUIDFromBytes((h.absolutePos(BlockPos.ZERO)+name).getBytes(java.nio.charset.StandardCharsets.UTF_8));
        if(net.neoforged.fml.ModList.get().isLoaded("ftbteams"))try{var api=Class.forName("dev.ftb.mods.ftbteams.api.FTBTeamsAPI").getMethod("api").invoke(null);var manager=Class.forName("dev.ftb.mods.ftbteams.api.FTBTeamsAPI$API").getMethod("getManager").invoke(api);if(!factorycraft.compatibility.FtbTeamsBridge.exists(uuid))Class.forName("dev.ftb.mods.ftbteams.api.TeamManager").getMethod("createServerTeam",net.minecraft.commands.CommandSourceStack.class,String.class,String.class,Class.forName("dev.ftb.mods.ftblibrary.icon.Color4I"),UUID.class).invoke(manager,h.getLevel().getServer().createCommandSourceStack(),"FactoryCraft QA "+name,null,null,uuid);return "ftb:"+uuid;}catch(ReflectiveOperationException e){throw new IllegalStateException("FTB Teams QA setup failed",e);}
        return "player:"+uuid;}
    @GameTest(template="empty",timeoutTicks=650)
    public static void poweredLabsShareUnitsAndSpendExactlyOnePackPerUnit(GameTestHelper h){var scope=personal(h,"shared");var a=lab(h,3,scope);var b=lab(h,8,scope);var data=ResearchData.get(h.getLevel().getServer());var tech=ResearchCatalog.get(h.getLevel()).entry(id("automation"));data.team(scope).select(tech.logic());
        h.runAfterDelay(5,()->{a.items.setStackInSlot(0,new ItemStack(Content.SCIENCE_RED.get(),10));b.items.setStackInSlot(0,new ItemStack(Content.SCIENCE_RED.get(),10));a.power.restore(16000);b.power.restore(16000);});
        h.runAfterDelay(460,()->{h.assertTrue(data.team(scope).level(id("automation").toString())==1,"labs did not finish shared research");h.assertTrue(a.items.getStackInSlot(0).getCount()+b.items.getStackInSlot(0).getCount()==10,"two labs overspent final unit");h.assertTrue(data.team(personal(h,"isolated")).level(id("automation").toString())==0,"research leaked across teams");h.succeed();});}
    @GameTest(template="empty",timeoutTicks=160)
    public static void labPausesWithoutEnergyAndWhenAPartIsUnavailable(GameTestHelper h){var scope=personal(h,"pause");var lab=lab(h,4,scope);var data=ResearchData.get(h.getLevel().getServer());data.team(scope).select(ResearchCatalog.get(h.getLevel()).entry(id("automation")).logic());lab.items.setStackInSlot(0,new ItemStack(Content.SCIENCE_RED.get(),3));
        h.runAfterDelay(20,()->{h.assertTrue(lab.progress()==0 && lab.items.getStackInSlot(0).getCount()==3,"unpowered lab spent packs");lab.power.restore(16000);});
        h.runAfterDelay(35,()->{var part=(CasingBlockEntity)h.getLevel().getBlockEntity(lab.assembly().positions().getLast());part.onChunkUnloaded();int work=lab.progress(),fe=lab.power.getEnergyStored();h.runAfterDelay(25,()->{h.assertTrue(lab.progress()==work && lab.power.getEnergyStored()==fe && lab.inventory().extractItem(0,1,false).isEmpty(),"unloaded lab advanced or exposed cached contents");part.onLoad();});});
        h.runAfterDelay(120,()->{h.assertTrue(data.team(scope).units(ResearchCatalog.get(h.getLevel()).entry(id("automation")).logic())>0,"lab did not resume");h.succeed();});}
    @GameTest(template="empty",timeoutTicks=100)
    public static void vanillaTeamsShareResearchAndMembershipChangesDoNotCopyIt(GameTestHelper h){if(net.neoforged.fml.ModList.get().isLoaded("ftbteams")){h.succeed();return;}var a=h.makeMockPlayer(GameType.SURVIVAL);var board=h.getLevel().getScoreboard();String name="fc"+UUID.randomUUID().toString().substring(0,8);var team=board.addPlayerTeam(name);board.addPlayerToTeam(a.getScoreboardName(),team);String scope=ResearchTeams.resolve(a).orElseThrow();h.assertTrue(scope.equals("vanilla:"+name),"vanilla team not selected");var data=ResearchData.get(h.getLevel().getServer());var tech=ResearchCatalog.get(h.getLevel()).entry(id("automation")).logic();data.team(scope).select(tech);data.team(scope).completeUnit(tech,()->{});board.removePlayerFromTeam(a.getScoreboardName(),team);String individual=ResearchTeams.resolve(a).orElseThrow();h.assertTrue(individual.startsWith("player:") && data.team(individual).units(tech)==0 && data.team(scope).units(tech)==1,"leaving team copied or erased research");board.removePlayerTeam(team);h.succeed();}
    @GameTest(template="empty",timeoutTicks=100)
    public static void unlocksAffectOwnedMachinesButPreserveLegacyFactories(GameTestHelper h){var scope=personal(h,"gates");var catalog=ResearchCatalog.get(h.getLevel());h.assertTrue(!catalog.allowed(scope,id("logistic_science_pack"),h.getLevel()) && catalog.allowed("",id("logistic_science_pack"),h.getLevel()) && catalog.allowed(scope,id("iron_gear"),h.getLevel()),"bootstrap/legacy gating incorrect");var ledger=ResearchData.get(h.getLevel().getServer()).team(scope);var tech=catalog.entry(id("automation")).logic();ledger.select(tech);for(int i=0;i<10;i++)ledger.completeUnit(tech,()->{});h.assertTrue(catalog.allowed(scope,id("logistic_science_pack"),h.getLevel()),"completed research did not unlock production");h.succeed();}
    @GameTest(template="empty",timeoutTicks=100)
    public static void technologyNativeJsonWireAndPrerequisitesRemainReadable(GameTestHelper h){var recipe=ResearchCatalog.get(h.getLevel()).entry(id("batteries")).recipe();var ops=net.minecraft.resources.RegistryOps.create(com.mojang.serialization.JsonOps.INSTANCE,h.getLevel().registryAccess());var json=TechnologyRecipe.CODEC.codec().encodeStart(ops,recipe).getOrThrow();h.assertTrue(TechnologyRecipe.CODEC.codec().parse(ops,json).getOrThrow().unlocks().contains(id("battery")),"technology JSON lost unlock");var b=new net.minecraft.network.RegistryFriendlyByteBuf(io.netty.buffer.Unpooled.buffer(),h.getLevel().registryAccess());try{var codec=Content.RESEARCH_SERIALIZER.get().streamCodec();codec.encode(b,recipe);h.assertTrue(codec.decode(b).packs().size()==2,"technology wire lost packs");}finally{b.release();}h.succeed();}
    @GameTest(template="empty",timeoutTicks=3600)
    public static void automatedScienceLineActuallyUnlocksLogisticPacks(GameTestHelper h){var scope=personal(h,"automatic");var o=h.absolutePos(new BlockPos(1,2,1));factorycraft.diagnostics.ResearchFactory.build(h.getLevel(),o,scope);h.runAfterDelay(3200,()->{var ledger=ResearchData.get(h.getLevel().getServer()).team(scope);h.assertTrue(ledger.level(id("automation").toString())==1 && ResearchCatalog.get(h.getLevel()).allowed(scope,id("logistic_science_pack"),h.getLevel()),"automatic science did not unlock technology");h.succeed();});}
    @GameTest(template="empty",timeoutTicks=100)
    public static void portableLabKeepsTeamPacksAndFreshPartOwnership(GameTestHelper h){var scope=personal(h,"portable");var lab=lab(h,3,scope);h.runAfterDelay(5,()->{lab.items.setStackInSlot(0,new ItemStack(Content.SCIENCE_RED.get(),7));lab.power.restore(7312);var old=lab.assembly().identity();h.getLevel().destroyBlock(lab.assembly().positions().getLast(),true);var drops=h.getLevel().getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new net.minecraft.world.phys.AABB(lab.getBlockPos()).inflate(4));h.assertTrue(drops.size()==1,"lab demolition copied packs");var player=h.makeMockPlayer(GameType.SURVIVAL);player.setYRot(Direction.SOUTH.toYRot());player.setItemInHand(net.minecraft.world.InteractionHand.MAIN_HAND,drops.getFirst().getItem().copy());drops.getFirst().discard();var pos=h.absolutePos(new BlockPos(9,2,4));h.assertTrue(PlacementTestSupport.place(player,pos).consumesAction(),"portable lab placement failed");var restored=(LabBlockEntity)h.getLevel().getBlockEntity(pos);h.assertTrue(restored.scope().equals(scope) && restored.items.getStackInSlot(0).getCount()==7 && restored.power.getEnergyStored()==7312 && !old.equals(restored.assembly().identity()),"portable lab lost state or identity");h.succeed();});}
    @GameTest(template="empty",timeoutTicks=220)
    public static void actualOwnedAssemblerWaitsForTeamUnlock(GameTestHelper h){var pos=h.absolutePos(new BlockPos(4,2,4));StructurePlacement.place(h.getLevel(),pos,Content.FACTORY.get(FactoryKind.ASSEMBLER).get().defaultBlockState());var machine=(MachineBlockEntity)h.getLevel().getBlockEntity(pos);var scope=personal(h,"assembler");machine.bindResearch(scope);h.runAfterDelay(5,()->{machine.items.setStackInSlot(0,new ItemStack(Content.FACTORY.get(FactoryKind.BELT).get()));machine.items.setStackInSlot(1,new ItemStack(Content.FACTORY.get(FactoryKind.INSERTER).get()));machine.power.restore(5000);});h.runAfterDelay(40,()->{h.assertTrue(machine.items.getStackInSlot(4).isEmpty() && machine.power.getEnergyStored()==5000,"locked production spent resources");var ledger=ResearchData.get(h.getLevel().getServer()).team(scope);var tech=ResearchCatalog.get(h.getLevel()).entry(id("automation")).logic();ledger.select(tech);for(int i=0;i<10;i++)ledger.completeUnit(tech,()->{});});h.runAfterDelay(190,()->{h.assertTrue(machine.items.getStackInSlot(4).is(Content.SCIENCE_GREEN.get()) && machine.power.getEnergyStored()==2600,"unlocked machine did not produce science");h.succeed();});}
    @GameTest(template="empty",timeoutTicks=100)
    public static void networkSelectionRequiresCurrentMenuTeamAndPrerequisites(GameTestHelper h){if(net.neoforged.fml.ModList.get().isLoaded("ftbteams")){h.succeed();return;}var player=net.neoforged.neoforge.common.util.FakePlayerFactory.getMinecraft(h.getLevel());var scope=ResearchTeams.resolve(player).orElseThrow();var lab=lab(h,4,scope);for(var cell:MachineProfile.LAB.cells(lab.getBlockPos(),Direction.NORTH))h.getLevel().getBlockEntity(cell).onLoad();player.moveTo(lab.getBlockPos().getX()+.5,lab.getBlockPos().getY(),lab.getBlockPos().getZ()+.5);var menu=new ResearchMenu(91,player.getInventory(),lab);var previous=player.containerMenu;player.containerMenu=menu;try{h.assertTrue(!ResearchNetwork.select(player,new ResearchNetwork.Select(92,id("automation"))) && !ResearchNetwork.select(player,new ResearchNetwork.Select(91,id("batteries"))) && ResearchNetwork.select(player,new ResearchNetwork.Select(91,id("automation"))),"menu or prerequisite validation failed");var board=h.getLevel().getScoreboard();var team=board.addPlayerTeam("net"+UUID.randomUUID().toString().substring(0,8));board.addPlayerToTeam(player.getScoreboardName(),team);h.assertTrue(!ResearchNetwork.select(player,new ResearchNetwork.Select(91,id("automation"))),"team-changing player kept control of old lab");lab.items.setStackInSlot(0,new ItemStack(Content.SCIENCE_RED.get(),2));menu.setCarried(ItemStack.EMPTY);menu.clicked(0,0,net.minecraft.world.inventory.ClickType.PICKUP,player);h.assertTrue(lab.items.getStackInSlot(0).getCount()==2 && menu.getCarried().isEmpty(),"stale menu extracted another team's science");board.removePlayerFromTeam(player.getScoreboardName(),team);board.removePlayerTeam(team);}finally{player.containerMenu=previous;}h.succeed();}
    @GameTest(template="empty",timeoutTicks=100)
    public static void teamLedgerAndPortableLabPersistAcrossServerProcesses(GameTestHelper h){var pos=new BlockPos(623,70,623);var cells=MachineProfile.LAB.cells(pos,Direction.NORTH);for(var cell:cells)h.getLevel().getChunkAt(cell);String scope="player:7f50a122-b81a-4333-9741-b864fd067821";var data=ResearchData.get(h.getLevel().getServer());var tech=ResearchCatalog.get(h.getLevel()).entry(id("automation")).logic();
        if(h.getLevel().getBlockEntity(pos)==null){StructurePlacement.place(h.getLevel(),pos,Content.FACTORY.get(FactoryKind.LAB).get().defaultBlockState());var lab=(LabBlockEntity)h.getLevel().getBlockEntity(pos);lab.bind(scope);lab.items.setStackInSlot(0,new ItemStack(Content.SCIENCE_RED.get(),7));lab.power.restore(7312);data.team(scope).select(tech);for(int i=0;i<3;i++)data.team(scope).completeUnit(tech,()->{});data.setDirty();System.out.println("FACTORYCRAFT_RESEARCH_DISK: SEEDED team units, lab packs/FE and four-chunk identity");}
        else{var lab=(LabBlockEntity)h.getLevel().getBlockEntity(pos);h.assertTrue(lab.scope().equals(scope) && lab.items.getStackInSlot(0).getCount()==7 && lab.power.getEnergyStored()==7312 && data.team(scope).units(tech)==3,"research disk state changed");for(var cell:lab.assembly().positions())h.assertTrue(h.getLevel().getBlockEntity(cell) instanceof CasingBlockEntity part && part.boundTo(pos,lab.assembly().identity()),"lab part identity changed");System.out.println("FACTORYCRAFT_RESEARCH_DISK: VERIFIED exact team units, lab packs/FE and identity");}
        for(var cell:cells){var be=h.getLevel().getBlockEntity(cell);if(be!=null)be.onChunkUnloaded();h.getLevel().getChunkAt(cell).setUnsaved(true);}h.succeed();}
}
